def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    change_ratio = change / v1
    percent_change = change_ratio * 100

    return {
        "value": percent_change,
        "trace": {
            "2004_value": v1,
            "2005_value": v2,
            "absolute_change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percent"
            }
        }
    }
